const seen = new Set<number>();
const totals = new Map<string, number>();
for (const row of rows) {
  if (seen.has(row.id)) continue;
  seen.add(row.id);
  if (row.status !== "paid") continue;
  const amount = row.quantity * row.unitPrice * (1 - (row.discount ?? 0));
  totals.set(row.customer, (totals.get(row.customer) ?? 0) + amount);
}
const result: Array<{ customer: string; revenue: number }> = [];
for (const [customer, total] of totals) {
  result.push({ customer, revenue: Math.round((total + Number.EPSILON) * 100) / 100 });
}
result.sort((a, b) => b.revenue - a.revenue || (a.customer < b.customer ? -1 : a.customer > b.customer ? 1 : 0));
return result.slice(0, 5);

