// Made-up rows: every example order is paid and has its own order number, so the examples test the arithmetic,
// the ranking and the grouping; the house rules (properties) test refunds and repeated order numbers.
const row = (id: number, customer: string, quantity: number, unitPrice: number, more: { discount?: number | null; country?: string } = {}) => ({
  id,
  orderDate: '2024-01-01',
  customer,
  email: 'made.up@example.com',
  country: more.country ?? 'France',
  product: 'Made-up item',
  quantity,
  unitPrice,
  discount: more.discount ?? null,
  status: 'paid',
});

test("One order of 2 × $10.00 gives $20.00", () => {
  eq(topCustomersByRevenue([row(1, 'Customer A', 2, 10)]), [{ customer: 'Customer A', revenue: 20 }]);
});

test("A 25% discount on 4 × $5.00 gives $15.00", () => {
  eq(topCustomersByRevenue([row(1, 'Customer A', 4, 5, { discount: 0.25 })]), [{ customer: 'Customer A', revenue: 15 }]);
});

test("Two customers tied at $50.00 are listed A to Z", () => {
  eq(topCustomersByRevenue([row(1, 'Customer B', 5, 10), row(2, 'Customer A', 2, 25)]), [
    { customer: 'Customer A', revenue: 50 },
    { customer: 'Customer B', revenue: 50 },
  ]);
});

test("Seven customers: only the top 5 come back", () => {
  const seven = ['A', 'B', 'C', 'D', 'E', 'F', 'G'].map((c, i) => row(i + 1, 'Customer ' + c, i + 1, 10));
  eq(topCustomersByRevenue(seven), [
    { customer: 'Customer G', revenue: 70 },
    { customer: 'Customer F', revenue: 60 },
    { customer: 'Customer E', revenue: 50 },
    { customer: 'Customer D', revenue: 40 },
    { customer: 'Customer C', revenue: 30 },
  ]);
});

test("An empty file gives an empty list", () => {
  eq(topCustomersByRevenue([]), []);
});

test("One customer in two countries is one line", () => {
  eq(topCustomersByRevenue([row(1, 'Customer A', 1, 10, { country: 'France' }), row(2, 'Customer A', 2, 10, { country: 'Japan' })]), [
    { customer: 'Customer A', revenue: 30 },
  ]);
});

